      addIssue(
        "high",
        "design",
        "AgentZ Forms Chrome is INERT: its scope matches no rendered container, so native Forms controls are unstyled. " +
          "The chrome is scoped to the Forms iPart's ContentItemName — re-place with imis_page_iparts formsChrome=true, " +
          "or run imis_design_system action=reskin to re-scope it",
        "declaredScope " + (chrome.declaredScope || "(unstamped)") +
          "; renderedFormContainers " + (chrome.observedFormContainerIds || []).join(", "),
      );
